sys_script_fix.script:
const NEED_IT = new GlideRecord('x_58872_needit_needit');

NEED_IT.addQuery('u_requested_for_email', '');
NEED_IT.query();
while(NEED_IT.next()) {
	NEED_IT.setValue(
		'u_requested_for_email',
		`${NEED_IT.getDisplayValue('u_requested_for').toLocaleLowerCase().split(' ').join('.')}@example.com`
	);
	NEED_IT.update();
}
